#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param([Parameter(Mandatory)][string]$Directory)
$ErrorActionPreference='Stop'
$root='<repo>'
$inventory=Get-Content -LiteralPath (Join-Path $Directory 'expected-inventory.json') -Raw|ConvertFrom-Json
$chain=Get-Content -LiteralPath (Join-Path $Directory 'chain-completion.json') -Raw|ConvertFrom-Json
if($chain.failure -or @($chain.phases).Count -ne 5 -or @($chain.phases|Where-Object exitCode -NE 0).Count -or @($chain.preparation).Count -ne 4 -or @($chain.preparation|Where-Object exitCode -NE 0).Count){throw 'Review preparation requires the full completed passing chain'}
if((& git -C $root rev-parse HEAD).Trim() -cne $inventory.revision){throw 'Candidate revision changed'}
$relativeFiles=@(
 'AGENTS.md','README.md','docs/release15-completion-plan.md','docs/admin_pwa_release.md','docs/implementation_plan.md','docs/deployment_plan.md','docs/hosting_execution.md','docs/moderation_plan.md','docs/local_development.md','docs/architecture_design.md','docs/room_sync_fix.md','docs/submission/README.md','docs/submission/hv-evidence.md',
 'docs/receipts/hv/20261029T102510-admin-pwa-source-round6.verdict.json','docs/evidence/release15/selfcheck/selfcheck.md','docs/evidence/release15/pre-hv-mapping-selfcheck.json','docs/evidence/release15/frozen-0fb37e6/pre-hv-what-if.json','docs/evidence/release15/request-diagnostics/receipt.json','docs/evidence/release15/request-diagnostics/style-followup.json','docs/evidence/release15/reviewer-gate-amendment.json','docs/evidence/release15/qbrain-update-receipt.json','docs/evidence/release15/wiki-publish-receipt.json',
 'docs/testing/ui/cases/TEST-ADMINUI-136.md','tests/browser/request-diagnostics.ts','tests/browser/request-diagnostics.contract.ts','tests/browser/request-diagnostics.test.ts','tests/browser/live-player-counts.integration.spec.ts','tests/browser/live-multiplayer.integration.spec.ts',
 'docs/evidence/release15/frozen-0fb37e6/encrypted-game-backup-index-v2.json','docs/evidence/release15/frozen-0fb37e6/backup-20261030T171009-fba382bf-staging.json','docs/evidence/release15/frozen-0fb37e6/backup-20261030T171025-c2196e52-production.json',
 'docs/evidence/release15/frozen-131269a/diagnostics-what-if-supplement.json','docs/evidence/release15/frozen-131269a/diagnostics-selfreview.md','docs/evidence/release15/frozen-131269a/initial-ui-presence-policy-audit.json','docs/evidence/release15/frozen-131269a/wiki-publication-repair/index.json','docs/evidence/release15/frozen-131269a/wiki-publication-repair/receipt.json','docs/evidence/release15/frozen-131269a/wiki-publication-repair/semantic-readback-normalized.json','docs/evidence/release15/readiness-barrier/plan.md','docs/evidence/release15/readiness-barrier/receipt.json','tests/browser/readiness-barrier.ts','tests/browser/readiness-barrier.contract.ts','tests/browser/readiness-barrier.test.ts',
 'docs/evidence/release15/hosting-readiness/guarded-rollout-procedure.md','docs/evidence/release15/hosting-readiness/guarded-rollout-receipt.json','docs/evidence/release15/frozen-cca320b/submission-source-followup.json',
 'docs/evidence/release15/command-capture/plan.md','docs/evidence/release15/command-capture/receipt.json','tests/browser/ui-command-capture.ts','tests/browser/ui-command-capture.contract.ts','tests/browser/ui-command-capture.test.ts'
)
$files=@($relativeFiles|ForEach-Object {Join-Path $root $_})+@((Join-Path $Directory 'source-what-if-supplement.json'),(Join-Path $Directory 'source-selfreview.md'),(Join-Path $Directory 'client-boundary.json'),(Join-Path $Directory 'chain-completion.json'))
$pins=@(foreach($path in $files){[pscustomobject]@{path=$path;sha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash}})
$selfPath=Join-Path $Directory 'source-self-review.json'
$briefPath=Join-Path $Directory 'cline-review-brief.md'
if((Test-Path -LiteralPath $selfPath) -or (Test-Path -LiteralPath $briefPath)){throw 'Retain prior review preparation; do not overwrite'}
$checklist=[ordered]@{
 holisticReview=@{passed=$true;evidence=@((Join-Path $root 'docs/release15-completion-plan.md'),(Join-Path $Directory 'source-selfreview.md'),(Join-Path $root 'docs/evidence/release15/selfcheck/selfcheck.md'));reason='Root read the current whole plans/designs, source changes, native failure and retained Claude round6 verdict. Current gate is source readiness for staging, with hosted/physical/submission proof explicit rather than claimed.'}
 whatIf=@{passed=$true;evidence=@((Join-Path $root 'docs/evidence/release15/frozen-0fb37e6/pre-hv-what-if.json'),(Join-Path $root 'docs/evidence/release15/frozen-131269a/diagnostics-what-if-supplement.json'),(Join-Path $Directory 'source-what-if-supplement.json'));reason='Prior45-record207-criterion360-axis source audit and diagnostics supplement retain historical source scope; the current supplement binds readiness and command-capture deltas, including combined body/action failure retention, to this candidate and checks unchanged source paths. Exact execution, causal and chronology limitations remain explicit; no prior approval transfers.'}
 propagationAudit=@{passed=$true;evidence=@((Join-Path $Directory 'core-index/evidence-index.json'),(Join-Path $root 'docs/evidence/release15/frozen-131269a/wiki-publication-repair/index.json'));reason='Capacity/reviewer/docs reconciled with QBrain;935wiki hrefs normalized on92pages with108published blobs verified and4historical missing images explicit. Raw export preserved;168semantic requirements/1427edges unchanged. Qualifier-aware22-case docs drift and indexed provenance are in the current frozen run. Test-only repairs change no product behavior or criterion satisfaction.'}
 phaseBoundary=@{passed=$true;evidence=@((Join-Path $root 'docs/evidence/release15/request-diagnostics/receipt.json'),(Join-Path $root 'docs/evidence/release15/readiness-barrier/receipt.json'),(Join-Path $root 'docs/evidence/release15/command-capture/receipt.json'),(Join-Path $Directory 'chain-completion.json'));reason='Diagnostics/readiness/command-capture oracles have retained independent correct/wrong fixture gates before implementation and identical real binding; inspect each chronological receipt. Complete current frozen gates follow. Hosted migration/deployment and physical OAuth/install evidence remain later dependencies.'}
 searchBeforeAdding=@{passed=$true;evidence=@((Join-Path $Directory 'source-selfreview.md'),(Join-Path $root 'docs/evidence/release15/selfcheck/selfcheck.md'));reason='Swept equivalent command observation paths in both live specs, retained shared cleanup, and checked Request identity, eager capture, body/action error siblings and exact-payload recovery. Prior single-holdout attribution remains a source-supported inference from11snapshots/domain policy, without a recorded runtime database deadline. Reused canonical UI commands/source manifests/validator indices/Cline runtime/plugin/native configuration.'}
 noNewMechanism=@{passed=$true;evidence=@((Join-Path $root 'tests/browser/request-diagnostics.ts'),(Join-Path $root 'tests/browser/readiness-barrier.ts'),(Join-Path $root 'tests/browser/ui-command-capture.ts'));reason='No new game protocol, provider or app dependency. Test instrumentation owns exact Request response/body work and both failure branches; readiness waits for every existing rendered preparation condition. Application policy/cap/deadlines and retry bounds are unchanged; matrix body-error recovery requires actual same-page enabled pending UI and an identical original payload. Strict keeps its four-conflict-only semantics.'}
 mappingLint=@{passed=$true;evidence=@((Join-Path $root 'docs/evidence/release15/pre-hv-mapping-selfcheck.json'),(Join-Path $root 'docs/evidence/release15/frozen-131269a/wiki-publication-repair/semantic-readback-normalized.json'),(Join-Path $Directory 'source-what-if-supplement.json'));reason='Existing semantic mappings/criteria preserved and independently checked; no standalone AC type, stable-ID replacement or satisfaction mutation. Fresh168effective records/1427edges unchanged. Reviewer must query current QBrain through its own plugin.'}
 operatorScopeVerbatim=@{passed=$true;evidence=@($briefPath);reason='The completed brief carries the exact operator decisions and four mandatory review surfaces, entire outcome and explicit evidence boundaries.'}
 standingRulesDelegated=@{passed=$true;evidence=@($briefPath);reason='Brief requires literal profile/live memories, matching Cline plugin, honest source/model/effort identity, PowerShell checks, no test/build execution, full JSONL, progress and full reviewer-owned MCP verdict readback.'}
}
$self=[pscustomobject]@{timestamp=(Get-Date -Format s);revision=$inventory.revision;runId=$inventory.runId;parentSessionId='Codex-20261027T100516Z-plugin-session';parentRequestId='req-20261030T203656Z-cline-beam-release';gate='Source candidate readiness for staging only; not hosted release completion';classification='Same-family holistic self-review, not independent hostile approval';inspectedFiles=$pins;checklist=$checklist;observed='Full current chain native receipts and all12TRX are supplied; prior failures/chronology unknowns are preserved.';remaining=@('Actual Cline model stream and reviewer-owned complete verdict/readback','Forward012/013 staging then production, exact reviewed deployment and hosted functional observations','Live GitHub consent, standalone phone cookie continuity and physical OS install observations','Authenticated mission/Code of Conduct and subsequent Work coding remain unverified; shared planning source is now accessible, not full workflow proof; no contest-entry/terms acceptance claim');accuracy=99;completeness=95;ratingReason='Source readiness evidence is complete only for the scoped local gate; independent review, hosted rollout and physical/submission evidence remain pending.'}
$core=Get-Content -LiteralPath (Join-Path $Directory 'core-index/evidence-index.json') -Raw|ConvertFrom-Json
$supplemental=Get-Content -LiteralPath (Join-Path $Directory 'supplemental-index/supplemental-evidence-index.json') -Raw|ConvertFrom-Json
$reports=@($core.reports)+@($supplemental.reports)
function Get-ReviewReportText([string]$Name){
 $report=@($reports|Where-Object {$_.name -ceq $Name -or $_.kind -ceq $Name})
 if($report.Count -ne 1){throw "Review report absent or ambiguous: $Name"}
 $report[0]|ConvertTo-Json -Depth 18
}
$replacements=[ordered]@{
 '<FROZEN_SHA>'=$inventory.revision
 '<BASE_SHA>'='8e2f62417e0fe46cefd884e8a61024b12860a2cf'
 '<SOURCE_MANIFEST_PATH_AND_SHA256>'=((Join-Path $Directory 'source-inventory.json')+' SHA256 '+(Get-FileHash -LiteralPath (Join-Path $Directory 'source-inventory.json')).Hash)
 '<FINAL_EVIDENCE_INDEX_PATH_AND_SHA256>'=((Join-Path $Directory 'core-index/evidence-index.json')+' SHA256 '+(Get-FileHash -LiteralPath (Join-Path $Directory 'core-index/evidence-index.json')).Hash+'; supplemental '+(Join-Path $Directory 'supplemental-index/supplemental-evidence-index.json')+' SHA256 '+(Get-FileHash -LiteralPath (Join-Path $Directory 'supplemental-index/supplemental-evidence-index.json')).Hash)
 '<FINAL_SELF_REVIEW_PATH_AND_SHA256>'=($selfPath+'; its SHA256 is recorded by the launcher request before invocation')
 '<PRECISE_GATE_AND_IMPLEMENTER_CLAIMS>'=('Source readiness for staging at '+$inventory.revision+': complete local unit/SQL/browser/PowerShell/Realtime/14-game/strict lanes pass with source unchanged, requirements and linked wiki reconciled. Independent approval is requested; hosted rollout, native-phone behavior, contest compliance and final game completion remain unclaimed.')
 '<UNIT_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText unit)
 '<POSTGRES_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText postgres)
 '<BROWSER_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText browser)
 '<PLANNER_MOCK_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText planner-mock)
 '<PLANNER_REAL_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText planner-real)
 '<SCRIPT_CONTRACTS_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText script-contracts)
 '<DOCS_DRIFT_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText docs-drift)
 '<PROVENANCE_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText provenance)
 '<PREPARER_REAL_TRX_AND_FULL_PROVENANCE>'=((Join-Path $Directory 'preparer-real/Real.trx')+' SHA256 '+(Get-FileHash -LiteralPath (Join-Path $Directory 'preparer-real/Real.trx')).Hash+'; complete native gate and producing invocation in '+(Join-Path $Directory 'preparer-real/gate.json')+' and chain-completion.json; launcher appends full report.')
 '<REALTIME_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText realtime)
 '<LIVE_UI_14_TRX_AND_EACH_GAME_PROVENANCE>'=(Get-ReviewReportText live-ui)
 '<STRICT_UI_TRX_AND_FULL_PROVENANCE>'=(Get-ReviewReportText strict-ui)
 '<ALL_POWERSHELL_ANALYZER_AND_WHATIF_RECEIPTS>'=('Read '+(Join-Path $Directory 'powershell')+', docs/evidence/release15/freeze-preflight.json, request-diagnostics/ chronological receipts, and each archived producer validation/WhatIf receipt. Launcher copy and actual WhatIf are preserved at invocation. No historical missing order is repaired by a catch-up run.')
 '<TYPECHECK_LINT_BUILD_REPORTS>'=(Join-Path $Directory 'full/validation.json')
 '<INVENTORY_BEFORE_AFTER_AND_CLEAN_SOURCE_PROOF>'=(Join-Path $Directory 'source-inventory.json')
 '<MOCK_FIRST_CHRONOLOGY_AND_NEGATIVE_CONTROL_INDEX>'='docs/evidence/release15/request-diagnostics/receipt.json, docs/evidence/release15/readiness-barrier/receipt.json and docs/evidence/release15/command-capture/receipt.json; capacity/cleanup/admin UI and original chronology evidence named in the full current plan. Historical invitation/planner/docs-order gaps remain explicit. Frozen131269a was9pass/1fail/4skip; tenplayersready before finalpageconnected supports the5s single-holdout explanation by source policy, but no runtime database deadline was retained and causality is not proven. Currentbarrier requiresallpagesconnected/fullroster/ready-enabled beforeanyready. Command-capture V1mock/real56 and V2mock/real58 retain identical per-version oracles, including a pre-delta V2mock while V1helper stayed unchanged. Product policy and gameplayassertions remain unchanged.'
 '<CURRENT_QBRAIN_READBACK_AND_MAPPING_LINT>'='docs/evidence/release15/qbrain-update-receipt.json, reviewer-gate-amendment.json, pre-hv-mapping-selfcheck.json and current per-requirement/supplement; query effective QBrain read-only through your own plugin.'
 '<CURRENT_EXPORT_WIKI_REMOTE_BYTE_VERIFICATION>'='Original raw108file publication f0c112bdf8b535f5ba618da9355260153d73815e is preserved in docs/evidence/release15/wiki-publish-receipt.json. Latest93cc02daa6ef8e777fd8287fce9b2bd264de775e is explicitly href-normalized publication projection:935hrefs/92pages,108published blobs/hashverified, all274originalwiki files/rawZIP retained. Read frozen-131269a/wiki-publication-repair/index.json and full receipt.json inverse-proven transformations; current168semantic requirements/1427edges unchanged. Four historical /tmp images unavailable; source-only links pin local131269a awaiting applicationpush; externalGitHubrendering not exhaustively checked. No canonical requirement Markdown or behavior was hand-authored.'
 '<HOSTING_BACKUP_AND_ROLLOUT_CLAIM_RECEIPTS_OR_EXPLICIT_PENDING>'='Hosting rollout remains pending, older canonical observations are historical only. Read docs/evidence/release15/frozen-0fb37e6/encrypted-game-backup-index-v2.json (SHA256943A8697900DE655E19802234B0D0FB7387945ACAE5D017733A5E5C6BDDB572E), selected staging171009-fba382bf and production171025-c2196e52 receipts. Same read-only source/dump snapshot matched33tables per environment, projected schema/effective ACL and separately stable sequences; all five native exits0. All six attempts retained. Namespace/default ACL and view/type/sequence definitions not independently compared; managed auth/storage/Vault/cron/net/Realtime/external settings and unexercised cleanup fallback are explicit exclusions. Ciphertext originals and copied/pinned producer/tool remain private outside application Git. This is an operational APP/game logical roundtrip, not full-platform recovery, off-site storage, crash durability or independent HV.'
 '<RETAINED_FAILURE_AND_PRIOR_REVIEW_INDEX>'='docs/submission/hv-index.json; original Claude round6 verdict and frozen-b8400dc/frozen-0fb37e6 native failed receipts. No prior approval transfers to this candidate.'
 '<DURABLE_REQUEST_JSONL>'='the exact durable request JSONL path appended by the launcher below'
 '<DURABLE_RESPONSE_JSONL>'='the exact durable full response JSONL path appended by the launcher below'
 '<workspace>'=$root
}
$brief=Get-Content -LiteralPath /tmp/wordpairs-cline-review-brief-template.md -Raw
$brief=$brief.Replace('DRAFT ONLY. Root must replace every `<PLACEHOLDER>`, attach the actual frozen reports and verify source/evidence identity before launch. This draft is neither an executed review nor an approval.','This completed request supplies exact frozen reports and source/evidence identity. It is a request for independent review, not an executed review or approval.')
foreach($key in $replacements.Keys){$brief=$brief.Replace($key,[string]$replacements[$key])}
$brief=$brief.Replace('Root supplies the full actual files, not summaries.','Root supplies the full actual files, not summaries. Never run tests and never build code; inspect the supplied native reports and TRX read-only.')
$brief+="`n`nCURRENT FOLLOW-UP: Frozen cca320b is retained FAILED evidence: full684unit/63Postgres/86browser, PS46 and actualRealtime63+4 passed; matrix14cases was7pass/1fail(9players)/6skip, strict notrun. The9playergame reached round2 with16solves; all9snapshots stayed open/live/9of9 and player6 displayed Retry pending game request. The test driver's body read failed, but no exact old request/actor join or actual navigation was established. Read command-capture/plan.md and receipt.json: eager successful-body observation and existing same-command UI recovery must be judged separately. New body-error recovery is allowed only after a SAME-page visible/enabled pending control and exact original payload replay; absence remains an error. Inspect the actual oracle and source, never infer a passing current game from this repair history. The complete NEW matrix/strict reports attached above govern the current gate.`n`nCURRENT OPERATIONAL CLARIFICATIONS: Read docs/evidence/release15/hosting-readiness/guarded-rollout-procedure.md and its receipt. The older hosting_execution step6 manual exit1 means only the documented one-time Dashboard Redeploy checkbox. Retain BOTH global exit0 guards throughout and afterward. Do not send projectSettings.commandForIgnoringBuildStep: official REST docs explicitly say projectSettings persists to following deployments. No provider setting/deployment write was performed by this preparation. Read frozen-cca320b/submission-source-followup.json: the shared ChatGPT planning/design chat now renders in the browser; its final inspected response predates implementation. This qualifies earlier unavailable-source observations but proves neither later Work coding nor an uninspected mission clause. The mission reached actual Handshake sign-in after passive security verification. Account/terms/entry actions remain unperformed by the agent.`n"
if($brief -match 'DRAFT ONLY|<PLACEHOLDER>|<[A-Z][A-Z0-9_]+>|<workspace>'){throw 'Unfilled review placeholder'}
if(-not $PSCmdlet.ShouldProcess($Directory,'Write source-pinned holistic self-review and completed Cline Beam High brief')){return}
$self|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $selfPath
$brief|Set-Content -LiteralPath $briefPath
[pscustomobject]@{timestamp=(Get-Date -Format s);revision=$inventory.revision;runId=$inventory.runId;producer=$PSCommandPath;producerSha256=(Get-FileHash -LiteralPath $PSCommandPath).Hash;selfReview=$selfPath;selfReviewSha256=(Get-FileHash -LiteralPath $selfPath).Hash;brief=$briefPath;briefSha256=(Get-FileHash -LiteralPath $briefPath).Hash;qualification='Preparation only; launcher independently validates hard gates before any model invocation.'}|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $Directory 'review-preparation.json')
